238	    /**
239	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
240	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
241	     * the request body already rejects null and empty values, but permits whitespace-only strings
242	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
243	     * that gap so every required field must carry a non-blank value.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields
246	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
247	     */
248	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
249	        List<String> missing = new ArrayList<>();
250	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
251	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
252	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
253	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
254	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
255	        if (!missing.isEmpty()) {
256	            throw new InvalidOwnerFieldsException(missing);
257	        }
258	    }
259	
260	    private void addIfBlank(List<String> missing, String fieldName, String value) {
261	        if (value == null || value.isBlank()) {
262	            missing.add(fieldName);
263	        }
264	    }
265	
266	    /**
267	     * Normalizes the submitted {@code address} on create to its canonical form (see
268	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
269	     * stored and returned, and the form every later address comparison (the required-field check,
270	     * household duplicate detection and the shared household id) is judged on. A null address is left
271	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
272	     * after normalization likewise reduces to the empty string and is rejected there.
273	     *
274	     * @param ownerFieldsDto the submitted owner fields
275	     */
276	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
277	        String address = ownerFieldsDto.getAddress();
278	        if (address == null) {
279	            return;
280	        }
281	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
282	    }
283	
284	    /**
285	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
286	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
287	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
288	     * {@code 400 Bad Request}.
289	     *
290	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
291	     *                       {@link #rejectBlankOwnerFields} having already run)
292	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
293	     */
294	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
295	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
296	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
297	        ownerFieldsDto.setTelephone(normalized);
298	    }
299	
300	    /**
301	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
302	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
303	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
304	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
305	     *
306	     * @param ownerFieldsDto the submitted owner fields
307	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
308	     */
309	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
310	        String email = ownerFieldsDto.getEmail();
311	        if (email == null || email.isBlank()) {
312	            return;
313	        }
314	        email = email.trim();
315	        if (!EMAIL_PATTERN.matcher(email).matches()) {
316	            throw new InvalidOwnerFieldsException(List.of("email"));
317	        }
318	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
319	    }
320	
321	    /**
322	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
323	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
324	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
325	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
326	     *
327	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
328	     *                            {@link #normalizeTelephone}
329	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
330	     */
331	    private void rejectDuplicateTelephone(String normalizedTelephone) {
332	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
333	        boolean inUse = this.clinicService.findAllOwners().stream()
334	            .map(Owner::getTelephone)
335	            .filter(Objects::nonNull)
336	            .map(TelephoneNormalizer::toComparisonKey)
337	            .anyMatch(comparisonKey::equals);
338	        if (inUse) {
339	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
340	        }
341	    }
342	
343	    /**
344	     * Rejects creating an owner who shares a household with any existing owner, unless the request
345	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
346	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
347	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
348	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
349	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
350	     *
351	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
352	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
353	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
354	     *                                          request did not opt in with {@code sharesHousehold}
355	     */
356	    /**
357	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
358	     * both match the submitted values, compared case-insensitively. The count reflects only owners
359	     * already persisted at the time of the create, so the owner being created is never included.
360	     *
361	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
362	     *                  having already run)
363	     * @param lastName  the submitted last name (non-blank here)
364	     * @return the number of existing owners sharing the same first and last name
365	     */
366	    private int countNamesakes(String firstName, String lastName) {
367	        return (int) this.clinicService.findAllOwners().stream()
368	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
369	                && lastName.equalsIgnoreCase(owner.getLastName()))
370	            .count();
371	    }
372	
373	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
374	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
375	            return;
376	        }
377	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
378	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
379	        boolean inUse = this.clinicService.findAllOwners().stream()
380	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
381	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
382	            .anyMatch(comparisonKey::equals);
383	        if (inUse) {
384	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
385	        }
386	    }
387	}
